def neighbors(
    row: int, col: int, height: int, width: int
):
    for d_row, d_col in DIRECTIONS:
        next_row = row + d_row
        next_col = col + d_col
        if 0 &lt;= next_row &lt; height and 0 &lt;= next_col &lt; width:
