Keep this checker in a separate file such as check_hw1.py; do not paste it into the submitted hw1.py. It checks the path format and simulates keys and doors without changing the original grid. It does not prove that a legal path is shortest.
from hw1 import Solution

ROAD, DOOR, WALL, KEY, EXIT, PLAYER = range(6)


def path_is_legal(grid, path):
    if not path:
        return False

    board = [row[:] for row in grid]
    height = len(board)
    width = len(board[0])

    start = next(
        (r, c)
        for r, row in enumerate(board)
        for c, tile in enumerate(row)
        if tile == PLAYER
    )
    goal = next(
        (r, c)
        for r, row in enumerate(board)
        for c, tile in enumerate(row)
        if tile == EXIT
    )

    if path[0] != start:
        return False

    keys = 0
    previous = start
    for step in path[1:]:
        if not (
            isinstance(step, tuple)
            and len(step) == 2
            and all(isinstance(value, int) for value in step)
        ):
            return False

        row, col = step
        if not (0 &lt;= row &lt; height and 0 &lt;= col &lt; width):
            return False
        if abs(row - previous[0]) + abs(col - previous[1]) != 1:
            return False

        tile = board[row][col]
        if tile == WALL:
            return False
        if tile == KEY:
            keys += 1
            board[row][col] = ROAD
        elif tile == DOOR:
            if keys == 0:
                return False
            keys -= 1
            board[row][col] = ROAD

        previous = step

    return path[-1] == goal


