from collections import deque

def bfs(graph, start, goal):
    frontier = deque([start])
    parent = {start: None}
    expanded = []

    while frontier:
        state = frontier.popleft()
        expanded.append(state)
        if state == goal:
            return path_from(parent, goal), expanded

